INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04003','restaurante','Terraza Lamarlo','Chuletón y carnes en un patio-terraza con encanto; producto y ambiente.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04006','restaurante','Asador Ajo y Guindilla','Carnes a la brasa de gran nivel (entrecot, secreto) en una calle tranquila; servicio impecable.','gastronomia_ampliacion');
