INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18068','restaurante','Brasería La Cabaña de Dílar','Brasería de cachopo y migas con tradición del sidra-culín; producto y servicio de nivel.','gastronomia_ampliacion');
