INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23018','restaurante','Hotel-Restaurante La Alcaidía de Mágina','Cocina de Sierra Mágina con producto local y AOVE de la comarca, en un hotel rural de referencia.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23018','restaurante','Los Castillos','Cocina serrana tradicional y carnes, clásico del municipio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23019','restaurante','Restaurante Puerta de Arenas','Cocina casera muy valorada (choto, taco de lomo) junto a la GR-30; ambiente clásico y familiar.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23019','restaurante','Café-bar Virgen de la Cabeza','Parada de culto entre Jaén y Granada por sus desayunos y tostas; trato excelente (valoración sobresaliente).','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23020','restaurante','Mesón Casa Pepa','Costillas, flamenquín y tapas generosas de nueva gestión muy aplaudida.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23020','restaurante','Café Bar Porras','Bar junto al parque, ideal en verano; tapas sencillas y trato rápido y amable.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23021','restaurante','Bar ‘El Tejar’','Cocina casera de calidad: cordero, paletilla ibérica y guisos mediterráneos; parada tranquila en la A-4.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23021','restaurante','Restaurante Los Olivos y El Torogoz','Gran parada de carretera (A-4) de cocina sencilla, abierta 24 h.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23024','restaurante','Restaurante Del Arco','Cocina familiar de producto fresco y buena bodega; parada clásica entre Madrid y Andalucía.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23024','restaurante','Potro Blanco','Clásico de carretera (A-4) de cocina honesta y ambiente local.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23025','restaurante','Bar Las Ruedas','Tapas a elegir muy abundantes y choto; uno de los mejores tapeos del Condado, postres caseros.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23025','restaurante','Gilabert','Restaurante moderno de producto: tataki de atún, risotto de chipirón y carnes; muy buena relación calidad-precio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23026','restaurante','El Moreno','Cocina con chispa en la plaza: ensalada de queso de cabra, tartar de atún y aguacate, carnes; el referente del pueblo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23026','restaurante','Restaurante Casa Julia','Bar-restaurante céntrico de buen ambiente y precios ajustados; cocina casera.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23027','restaurante','Los Galgos','Bar de pueblo con buena comida, ambiente y precio; el referente del municipio (pocas reseñas).','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23029','restaurante','El Balcón de los Llanos','Cocina con vistas espectaculares: berenjenas con miel, mini- hamburguesas y boquerones; postres caseros.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23030','restaurante','Mesón La Cabaña','Carrillada y solomillo caseros, tapas y tostas; cocina muy cuidada y trato familiar.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23030','restaurante','Los Álamos','Tapas generosas y raciones bien presentadas; buen ambiente de pueblo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23031','restaurante','Bar La Vincula','Tapa recién hecha y famoso bocadillo de calamares; el bar de referencia del pueblo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23031','restaurante','Cafetería Memphis','Bocadillos, heladería y buen trato; ideal para meriendas y cenas informales.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23033','restaurante','Restaurante Angelillo','Queso local y jamón serrano, menú variado y de calidad; parada agradable con terraza.','gastronomia_ampliacion');
