INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23034','restaurante','Restaurante Escaramujo','Cocina de producto bien valorada: solomillo a la pimienta y ensalada Lulú; buen desayuno y café.','gastronomia_ampliacion');
