INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23035','restaurante','Café & Bar 4 Esquinas','Tapas y raciones generosas (espardeñas, ibéricos) con opciones sin gluten; en el centro.','gastronomia_ampliacion');
