INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23037','restaurante','Mesón Herrador','Tapas a elegir y secreto a la brasa; uno de los mejores bares de la Sierra (área de autocaravanas al lado).','gastronomia_ampliacion');
