INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23038','restaurante','Bar Restaurante Km. 42','Parrilla y cocina casera junto a la carretera: torreznos, entrecot de vaca madura y carnes a la brasa.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23039','restaurante','Restaurante Carlos III','Parrilla y guisos (carrilleras), espacioso y para eventos; trato muy cuidado.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23039','restaurante','Restaurante Las Tinajas','Curioso restaurante-anticuario a pie de la N-IV, comida casera; toda una experiencia.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23040','restaurante','Manuel’s Café Bar','Tapas gratis muy variadas, fritada de pescado y croquetas; cocina casera y buena terraza.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23041','restaurante','Café Bar El Rincón','Tapas caseras y ambiente familiar con parque infantil al lado; muy bien valorado.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23041','restaurante','Café Bar El Parque','Violetas y croquetas en una terraza entre jardines; referente local (pocas reseñas).','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23042','restaurante','Hotel Restaurante Valle del Turrilla','Terraza con vistas al valle, cocina serrana y piscina; escapada muy valorada cerca de Granada.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23042','restaurante','Café Bar Social','Tapas variadas y terraza acogedora; el bar del pueblo, muy recomendado por viajeros.','gastronomia_ampliacion');
