INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23044','restaurante','Bar Ideal','Institución del tapeo (reconocida por su tapa a nivel nacional): salmorejo, carrillada y producto de temporada en la Plaza de España.','gastronomia_ampliacion');
