INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23045','restaurante','Hotel Restaurante Sierra de Huesa','Menú serrano (sopa de garbanzos con pescado) y piscina en la azotea con vistas; parada de ruta muy valorada.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23045','restaurante','Restaurante Los Arcos','Tapas y pizzas con patio abierto muy agradable; un clásico para repetir en el pueblo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23046','restaurante','Bar La Esquina','Gastrobar que eleva el concepto de tapa con producto de calidad y cocina recién hecha; referente del municipio.','gastronomia_ampliacion');
