INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23049','restaurante','Restaurante Juan Ignacio','Tapas generosas y gran relación calidad-precio; bar de pueblo muy recomendable.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23049','restaurante','Restaurante Los Olivos','Gran parada de carretera (N-323a) con cocina honesta y servicio amplio; clásico de paso.','gastronomia_ampliacion');
