INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23051','restaurante','Café-Bar El Curi','Tapas y bocadillos ‘por metros’ en un bar tradicional muy querido en la comarca.','gastronomia_ampliacion');
