INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23053','restaurante','Los Molinos','Clásico familiar muy concurrido: salmorejo, bacalao al pil-pil y tapas generosas; el referente del municipio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23053','restaurante','Mesón Casa Jesús','Mesón de pueblo de cocina tradicional; choto al ajillo y guisos caseros.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23054','restaurante','Bar Buen Día','Bar de pueblo con vistas a Sierra Mágina; desayunos, tapas y cocina local sencilla (único referente del municipio).','gastronomia_ampliacion');
