INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23057','restaurante','Café Bar El Torreón de Lupión','Chopitos a la plancha y cocina casera en un local con encanto (paredes con obra del propietario).','gastronomia_ampliacion');
