INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23059','restaurante','Me lo como (Comida Casera)','Comida casera ‘de la abuela’, bien elaborada y a buen precio; muy recomendada para comer sano sin artificios.','gastronomia_ampliacion');
