INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23063','restaurante','Asador Restaurante El Cabo','Asador muy valorado por carnes, postres y trato familiar.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23063','restaurante','Restaurante La Alacena','Parrilla y producto (mollejas, oreja), con opciones sin gluten; cocina casera generosa.','gastronomia_ampliacion');
