INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23069','restaurante','Asador Torrelvira','Carnes a la brasa y el plato típico porcunero (las ‘violetas’), con huevos trufados; producto de calidad.','gastronomia_ampliacion');
