INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23070','restaurante','Taberna Paco Tite','Tapas típicas muy reputadas: patatas de cosecha propia, su famoso pollo frito, costillas y tarta de queso.','gastronomia_ampliacion');
