INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23073','restaurante','Restaurante El Curioso','Pequeño restaurante familiar de cocina casera muy cuidada; gran relación calidad-precio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23074','restaurante','La Bodega Rus','Bodega-restaurante de ambiente cuidado: cochinillo, presa ibérica y flamenquines; muy buena valoración.','gastronomia_ampliacion');
