INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23075','restaurante','Taberna El Minao','Tapas abundantes y sabrosas con vistas, muy del gusto local y viajero.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23076','restaurante','El Mesón Despeñaperros','Cocina serrana y de caza en plena puerta de Andalucía, parada clásica de la A-4.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23077','restaurante','Restaurante Pica Pica','‘Oasis en el olivar’: croquetas de rabo de toro y queso, lubina con risotto; cocina muy por encima de lo esperable. Reserva recomendable.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23079','restaurante','Los Sevillanos Gastrobar','Gastrobar de platos elaborados (huevos trufados, costillas), considerado lo mejor del pueblo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23079','restaurante','Restaurante Samper','Menú casero junto al yacimiento de huellas de dinosaurio; comedor amplio con chimenea.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23080','restaurante','Mesón Rural Baecula','Menú y tapeo con vistas, muy concurrido; cocina tradicional generosa.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23080','restaurante','Taberna El Refugio','Taberna de pueblo cuidada: calamares, patatas bravas y paella por encargo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23082','restaurante','Terraza La Piscina','Raciones y producto serrano (ventresca, carnes) con buena terraza; muy concurrido.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23082','restaurante','Los Barriles Restaurante','Chuletón, puerros y tarta de queso; cocina cuidada de nueva gestión.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23084','restaurante','Bar El Hogar','Tapas de primer nivel a precio imbatible; uno de los favoritos de la comarca (‘ganó la liga’).','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23084','restaurante','Return Café-Bar','Croquetas y bocadillos excelentes, parada de ciclistas; buen tapeo y servicio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23085','restaurante','Taberna Mirador de Cástulo','Menú y carta con vistas al mar de olivos y a Cástulo, con piscina; cocina variada muy valorada.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23085','restaurante','Gastrobar La Espuela','Gastrobar de tapas y parrilla (pescado frito, carnes) con terraza; trato muy cercano.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23086','restaurante','Restaurante El Duque','Cocina casera de toda la vida: paté de perdiz, flamenquín relleno de carrillada y queso, leche frita.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23086','restaurante','Restaurante Casa Vacas','Cocina casera honesta y carnes; fama local por sus patatas fritas y su trato.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23087','restaurante','El Mesón de Sergio','Cocina tradicional bien valorada, uno de los referentes para comer en el municipio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23088','restaurante','Restaurante La Recta Aguasblanquillas','Institución de carretera (Córdoba-Valencia) con miles de comensales: menú, pulpo y producto a buen precio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23088','restaurante','Taberna Paco Tite','Tapas y cocina casera de gran fama: patatas de cosecha propia, su célebre pollo frito y tarta de queso.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23091','restaurante','Mesón El Picarzo','Cocina casera y hamburguesas en un local acogedor; referente del municipio (pocas reseñas).','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23093','restaurante','El Quejigo del Carbón','Restaurante de aire actual sobre una loma (abierto en 2024), con amplias terrazas y carta variada de producto local.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23093','restaurante','Bar El Patatillas','Cocina casera del centro del pueblo; su plato alpujarreño (chorizo, morcilla y huevo frito) es clásico de invierno.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23094','restaurante','Hotel Restaurante Casa Marchena','Cocina casera de calidad (huevos rotos, repostería), el referente del municipio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23094','restaurante','Café Las Olas','Bar renovado junto a la iglesia de San Miguel; buenas tapas y terraza.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23095','restaurante','Restaurante Verde Olivo','Cocina cuidada de tapas y carta en una casa antigua junto a la iglesia, con patio; de lo mejor del pueblo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23095','restaurante','Mesón El Jardín','Taberna de pueblo con chimenea, jamones y ambiente auténtico; tapas tradicionales.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23096','restaurante','Sabores con Arte','Cafetería-heladería artesanal de referencia en el pueblo, con repostería propia y buen trato.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23096','restaurante','Bar Jaros','Bar de carácter con cocina casera: solomillos tiernos y gofres de postre.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23097','restaurante','Restaurante Moratilla','Cocina gastronómica de producto: steak tartar, arroz de boletus y costilla baja; sorprendente para la zona.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23097','restaurante','Café Larios','Desayunos ‘de lujo’ con selección de AOVE de Jaén y repostería; local elegante y muy valorado.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23098','restaurante','Bar El Rincón de Luz','Tapas y cervezas bien tiradas en un local con encanto; único referente del municipio (muy pocas reseñas).','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23099','restaurante','Restaurante El Embrujo Villariego','Cocina casera y menú muy completo; uno de los referentes para comer en el pueblo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23099','restaurante','Mesón Asador La Pandera','Asador con vistas en la subida a La Pandera; carnes a la brasa y producto de la zona.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23101','restaurante','Hostal Restaurante Las Eras','Hostal-restaurante junto a la plaza de toros, cocina casera y precios bajos, en pleno Parque Natural.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23902','restaurante','El Paraíso de Mágina','Cocina maginera de producto: andrajos, guisos de la huerta y caza de la sierra.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23902','restaurante','El Adelfal','Cocina tradicional y carnes, referente local en el casco urbano.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23903','restaurante','Restaurante El Recreo','Asador clásico de referencia con menú degustación que recorre Jaén y excelentes postres caseros; reserva imprescindible.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23904','restaurante','La Casa del Cordero (Pontones)','Cocina de montaña sin carta: plato tras plato de recetario local rematado por el cordero asado; experiencia muy alabada.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23904','restaurante','La Fonda del Perchel (Pontones)','Cocina serrana de producto, acogedora y muy valorada (también con viajeros del GR-247).','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23905','restaurante','Mesón El Albero','Mesón con jardín y parque al lado: tapas, menú y opciones sin gluten; parada muy agradable.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23905','restaurante','Restaurante Esencia','Menú del día de carretera muy valorado: carrillada al horno y oreja en salsa.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24001','restaurante','Restaurante Casa Mario','Asador de referencia: carnes a la brasa, berenjenas con miel de caña y arroces, con terraza muy concurrida en verano.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24001','restaurante','Bar restaurante Panocho','Tapas y raciones con vistas (flamenquín al roquefort, huevos rotos de la casa) tras las rutas de Aznaitín.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24003','restaurante','Restaurante Almocadén','Cocina cuidada y elaborada con materias primas de la zona: lomo de bacalao confitado y queso de cabra de Los Balanchares a la plancha. Un Sol Repsol.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24004','restaurante','Restaurante La Cimbarra','Migas y judiones a la lumbre, venado y tarta de queso, junto a la cascada; cocina casera muy alabada.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24004','restaurante','Bar de La Cruz','Venado y migas en la plaza, parada habitual al visitar La Cimbarra; trato amable.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24006','restaurante','Café-Bar-Restaurante El Gallo','Cocina de producto muy aplaudida (pulpo, atún rojo, bacalao); citado como de lo mejor entre Sevilla y Córdoba.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24006','restaurante','Restaurante Chuchy','Casa de cocina tradicional en la plaza: sopa de alcachofas, merluza y tapeo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24007','restaurante','Con Gusto Bistró-Arrocería','Bistró con menú diario y arroces de fin de semana; cocina cuidada, lo más completo del municipio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24007','restaurante','El Buen Sabor','Cocina casera y buen ambiente; bocadillos y platos del día.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24008','restaurante','Restaurante Tapería Alianza','Tapería de menú y eventos muy valorada; cocina casera y servicio cuidado.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24008','restaurante','Hostal Restaurante La Noria','Cocina casera de caza (venado, longaniza de pato), generosa y bien tratada.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24012','restaurante','Bury Restaurante','Cocina de autor que realza el producto local y un AOVE excepcional (Baluarte); menú degustación en un espacio íntimo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24012','restaurante','Mesón Santos','Cocina de caza (ciervo) y tapas en un mesón clásico, muy concurrido y bien valorado.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24013','restaurante','Restaurante Sótano Segurilla','Cocina de menú y pizzas artesanas en un comedor acogedor; muy bien valorado en el pueblo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24013','restaurante','Vita Bella / El Piano','Cocina con raíces de la Sierra y toque innovador, también pizza; ideal para tapear.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24015','restaurante','El Rincón del Gallo','Carta variada (hamburguesas, toques japoneses) y postres como la serradura; cocina muy querida en el pueblo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24015','restaurante','Bar Mesón Puente Viejo','Mesón rústico de cocina casera con menú de fin de semana; trato muy cuidado.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24016','restaurante','Cafetería Pub La Rambla','Tapas, cenas y heladería con muy buen ambiente; el mejor bar del pueblo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24018','restaurante','Restaurante Sierra Mágina','Bar-restaurante de tapas y cocina tradicional, referencia del municipio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24035','restaurante','Restaurante El Puente','Institución de las migas serranas (estación de Espelúy) y garbanzos con gambas; cocina de raíz y muy buen trato.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24086','restaurante','Bodegón de Bolero','Cocina casera andaluza muy acogedora: croquetas, ensaladilla y parrillada; trato excelente con senderistas.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24086','restaurante','Restaurante Asador Fuenmayor','Asador familiar con menú degustación asequible: codillo al horno y carnes; buen ambiente.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29028','restaurante','Restaurante BeJota','Croquetas de rabo de toro y berenjenas con miel en una terraza con vistas; cocina cuidada y trato excelente.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29028','restaurante','Asador El Muelle','Pescado y carnes a la brasa (solomillo ibérico) junto a la estación; ambiente andaluz y raciones generosas.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29032','restaurante','Taberna del Niño','Menú del día tradicional y las mejores natillas con galleta; tasca familiar muy querida.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29032','restaurante','Fermenta','Bar de quesos y vino: tabla de cinco quesos artesanos y croissant de rabo de toro; original (pocas reseñas).','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29033','restaurante','Secret Garden Restaurant','Cocina tailandesa de nivel en un jardín mágico de montaña: curry rojo, gambas en coco; singular y delicioso.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29038','restaurante','Miura Tragos y Bocados','Fusión de producto (gyozas de pato, cachopo) en Estación de Cártama; sabores originales y buen servicio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29038','restaurante','Tapería El Monte','Tapas y hamburguesas muy bien valoradas en el casco; trato cercano (pocas reseñas).','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29039','restaurante','La Posada Restaurante','Conejo, lomo y queso de cabra con nueces caramelizadas; joya escondida tras una puerta del centro.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29039','restaurante','Restaurante La Romana','Berenjenas con miel, cordero y cocina de pueblo; concurrido y de buen precio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29040','restaurante','Tomate Algo','Tapas artísticas de producto local con sabores únicos; merece el desvío tras el Caminito del Rey.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29040','restaurante','Restaurante La Parada','Paella, parrilla a la vista y cocina local; parada concurrida junto a la carretera.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29041','restaurante','Sarmiento','Asador a la brasa (‘la hermana mayor’) con vistas espectaculares al pueblo blanco; experiencia top.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29041','restaurante','Sunset','Pescado a la brasa (lubina) y cocina sencilla bien ejecutada con buenas vistas (pocas reseñas).','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29042','restaurante','Restaurante Casa Paco','Entrecot de vaca Ayrshire y pescado a la perfección; uno de los mejores asadores del valle.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29042','restaurante','Bodegón Casa Antonio','Tapas tradicionales en un ambiente local con mucha solera; producto y buen precio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29043','restaurante','La Taberna de Flores by Felipe Lopes','Cocina de producto (langostinos en tempura, lubina, tartar) con especiales diarios; servicio impecable.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29043','restaurante','La Esquina de la Morenita','Cocina interesante (chuletón, entrecot) y café de ciclistas; familiar y muy hospitalaria.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29045','restaurante','Restaurante El Pámpano','Rabo de toro y carnes a la brasa con terraza y puestas de sol; uno de los grandes de la Axarquía.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29045','restaurante','Mesón El Recreo','Tapas, cocina casera y pizza en una terraza soleada bajo la iglesia; gran relación calidad-precio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29046','restaurante','Mesón Los Alcornocales','Secreto ibérico, ensaladas y pollo a la brasa; el clásico del pueblo, muy concurrido.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29051','restaurante','Restaurante Kuvo','Menú degustación creativo de 13 pases a nivel casi Michelin; experiencia íntima y sobresaliente.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29051','restaurante','Grillhouse','Carnes y pescado a la brasa, brochetas y producto; uno de los más valorados del centro.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29053','restaurante','The Garden (El Jardín)','Cocina creativa en una de las mejores terrazas de la zona, con vistas al pueblo y al Mediterráneo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29053','restaurante','Old Town Restaurant & Bar','Cocina fresca de producto y tapas con vistas; pequeña joya muy bien valorada.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29056','restaurante','Platero & Co','Cocina mediterránea con vistas espectaculares: costillar de cordero, pato; oasis gastronómico.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29056','restaurante','La Raíz','Pulpo, lubina y T-bone con menú del día y vinos locales; servicio excelente y vistas de montaña.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29057','restaurante','El Patio Cocina Vegana','Cocina vegana de falafel, seitán casero y mozzarella vegetal con vino de Ronda; singular y delicioso.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29057','restaurante','Restaurante El Refugio','Cocina casera y tapas con buen vino local y vistas; ambiente del pueblo de los museos.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29060','restaurante','Bar Mena','Cocina casera (lentejas, panceta) y brownie de castaña en el bar de la plaza; gran relación calidad-precio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29061','restaurante','Raíces','Cocina local con toques creativos (costillas, cheesecake de queso de cabra) y vistas de montaña; casi Michelin.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29061','restaurante','Nuevo Entresierras','Arroz de bogavante y solomillo al whisky con terraza; cocina honesta de Diego, muy buen precio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29065','restaurante','Bar ParribaPabajo','Cocina casera y ensaladas con vistas y buen ambiente; trato muy cercano de la familia.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29065','restaurante','La Bodega del Bandolero','Cocina casera (solomillo, pizza) y pan recién horneado; agradable parada en el pueblo azul.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29068','restaurante','Asador A Grella','Asador de carnes a la brasa con raciones enormes en Sabinillas; auténtico y muy valorado.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29068','restaurante','Restaurante La Casita','Asador argentino y cocina mediterránea (pulpo, carrilleras); ambiente local muy querido.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29070','restaurante','Pampa Tablas y Tapas','Tablas y tapas de producto (gyozas, brasa) muy bien presentadas; lo mejor de Mijas Pueblo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29070','restaurante','Viento Sur Brunch Café','Brunch, tostas y hamburguesas en la plaza; desayunos memorables y trato cálido.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29073','restaurante','Café Bar Luna','Tapas caseras de gran formato y producto local; el bullicio del pueblo en la mesa.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29073','restaurante','De La Rubia','Tapas, paella y tortilla en pleno centro; raciones generosas y trato simpático.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29074','restaurante','Restaurante La Grulla','Pizzas de masa fina, tapas de atún y pan casero en un jardín mágico; de lo mejor de la zona.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29074','restaurante','Entre Ascuas & La Roca','Rabo de toro, venado y ravioli de trufa en la plaza; cocina de caza y trattoria.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29076','restaurante','Restaurante Boca Bistro','Bistró de steak tartare, gyozas y entrecot con servicio pausado y encantador; cocina de gran nivel.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29076','restaurante','La Placita','Tapas frescas y generosas con vino local en la plaza; hospitalidad de pueblo (pocas reseñas).','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29080','restaurante','El Rincón del Mohino','Pescado y marisco fresquísimo en un polígono (gambas, calamar): joya escondida que llena a diario.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29080','restaurante','La Algarbía','Tapas refinadas (fideos negros, bao de calamares) en el centro; cocina tradicional y de fusión.','gastronomia_ampliacion');
