INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29083','restaurante','Restaurante Diavolo','Cocina italiana de nivel (pasta, postres) con ambiente alegre; lo mejor de Riogordo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29083','restaurante','Raíces de María Jesús','Menú del día casero muy valorado en un local cuidado; trato familiar (pocas reseñas).','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29084','restaurante','El Lechuguita','Institución del tapeo (tapas a 1,50€ que eliges en una comanda): morcilla, lechuguita; siempre con cola, imprescindible.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29084','restaurante','Restaurante Casa María','Menú sorpresa de mercado sin carta (cada día distinto): cocina de producto memorable; reserva obligada.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29086','restaurante','El Ruano Restaurante Asador','Asador de carnes (solomillo) con vistas y terraza; trato cálido y celebraciones memorables.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29089','restaurante','Paripé Restaurante','Cocina creativa sorprendente (canelón de aguacate, pulpo, paella) impropia de un pueblo; muy recomendable.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29089','restaurante','Mesón de Diego','Tapas auténticas y cocina tradicional de gran volumen; parada clásica entre Ronda y Granada.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29090','restaurante','Restaurante Tolox','Croquetas, tartar de aguacate y pasta de pistacho; una sorpresa en la sierra (pocas reseñas).','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29090','restaurante','Enebro Restaurante','Carnes a la brasa y verduras asadas con producto local; cocina cuidada cerca del balneario.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29091','restaurante','Restaurante Magón','Sardinas ahumadas, entrecot y bacalao con puestas de sol en Torrox Costa; producto y servicio cuidados.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29091','restaurante','Bij Fleur','Cocina vegetariana y vegana fresca (hamburguesa de alubia negra) muy original; trato encantador (pocas reseñas).','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29094','restaurante','Restaurante Casa Lolo','Cocina casera de croquetas, brasa y paella con menú del día; servicio rápido y muy buen producto.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29094','restaurante','Bahía Beach Jazba','Chiringuito-restaurante de playa: paella, espeto y platos para compartir frente al mar; gran ambiente.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29100','restaurante','Carpe Diem Yunquera','Cocina inventiva casi Michelin (costillas BBQ, surf’n’turf) con opciones veg; gran descubrimiento de montaña.','gastronomia_ampliacion');
