INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30003','restaurante','El Poli','Producto del Mediterráneo con la gamba roja de Águilas como gran emblema. Un Sol Repsol.','gastronomia_ampliacion');
