INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30015','restaurante','La Gastrotasca El Taller de Sabores','Cocina km0 con productores locales, sostenibilidad y producto de temporada.','gastronomia_ampliacion');
