INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30015','restaurante','Rincón de Paco','Clásico de cocina tradicional murciana —rabo de toro— en un local de ambiente taurino.','gastronomia_ampliacion');
