INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30016','restaurante','La Marquesita','Cocina mediterránea y tapeo en el centro histórico. Solete Repsol.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30016','restaurante','El Cantón','Tapas y producto local en pleno casco antiguo. Solete Repsol.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30016','restaurante','La Posada de los Habaneros (Chef Juan Andrés Páez)','Cocina mediterránea con giros creativos frente a la Muralla Púnica.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30016','restaurante','El Mosqui','Templo del caldero del mar Menor y los arroces marineros a pie de faro. Un Sol Repsol.','gastronomia_ampliacion');
