INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30030','restaurante','AlmaMater (Chef Juan Guillamón)','Cocina murciana contemporánea de producto, técnica y memoria. Cuenta con una Estrella Michelin.','gastronomia_ampliacion');
