INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30030','restaurante','Polea','Cocina de mercado y producto de temporada. Un Sol Repsol.','gastronomia_ampliacion');
