INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48020','restaurante','Zortziko (Chef Daniel García)','Cocina de autor de raíz clásica, diseñada para sorprender en cada bocado. Una Estrella Michelin.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48020','restaurante','Etxanobe Atelier (Chef Fernando Canales)','Tradición vasca fusionada con la técnica de vanguardia. Una Estrella Michelin.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48020','restaurante','Gure Toki','Pintxos de autor premiados a nivel nacional en la Plaza Nueva del Casco Viejo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48020','restaurante','Los Fueros','Taberna bilbaína histórica (1878) con recetario tradicional revisitado.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48052','restaurante','Azurmendi (Chef Eneko Atxa)','Santuario de sostenibilidad e innovación; la experiencia arranca en el invernadero. Tres Estrellas Michelin y Estrella Verde.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48052','restaurante','Eneko (Chef Eneko Atxa)','Menú ''Sutan'', la versión más accesible de la cocina de Atxa. Una Estrella Michelin.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','restaurante','Zaldiaran','Alta cocina vasca con la trufa y una repostería premiada como sellos de la casa. Una Estrella Michelin.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','restaurante','Andere','Clásico vitoriano de producto y cocina vasca. Recomendado por la Guía Michelin.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','restaurante','Kea Basque Fine Food','Producto vasco de temporada con mirada actual. Recomendado por la Guía Michelin.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','restaurante','Karmine','Cocina vasca actual de mercado. Recomendado por la Guía Michelin.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','restaurante','144','Propuesta contemporánea de producto y temporada. Recomendado por la Guía Michelin.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90037','restaurante','Taberna del Zopo','Cocina tradicional española y tapeo en un ambiente familiar; producto y buen precio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90037','restaurante','Casa Pepe','Tapas y comida casera en un bar-restaurante familiar muy del pueblo.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90038','restaurante','Mare Nostrum','Pescado y marisco fresco, fritura y migas en el paseo marítimo; una pequeña joya.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90038','restaurante','Terraza Amanecer','Cócteles y pizzas en azotea con vistas al mar y al faro; ambiente y buen servicio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90419','restaurante','Bodega Andarax','Tapas variadas y originales con vino propio; ambiente y decoración muy cuidados.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90423','restaurante','Atípico Berja','Gastrobar de pintxos y platos con enfoque moderno (risotto de ibérico, torrija); gran descubrimiento (pocas reseñas).','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90423','restaurante','Restaurante Villavieja','Cocina mediterránea de raciones en un local amplio y familiar; buen precio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90430','restaurante','Restaurante Casa Piolas','Menú degustación de pases andaluces de producto local; cocina creativa de un chef brillante.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90430','restaurante','La Huella Gastrobar','Gastrobar de producto y menú sorpresa con AOVE propio; pequeña joya muy alabada.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90431','restaurante','La Maja 99','Tapas variadas, codillo y cachopo en un local muy bien decorado; servicio destacado.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90436','restaurante','Emilia Bistró','Bistró con toque argentino (empanadas) y tapas junto a la playa; desayunos y producto a buen precio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90436','restaurante','El Rincón de Jorge','Pescado fresco (lenguado a la plancha) y marisco; cocina casera española de gran nivel.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90438','restaurante','Restaurante Cienfuegos','Cocina mediterránea de nivel (tataki, tartar, carpaccio) con sala muy cuidada; de los mejores de la comarca.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90438','restaurante','Infinity Indian Restaurant','Cocina india de calidad (cordero rogan josh, baltis) muy valorada; alternativa distinta y bien ejecutada.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90439','restaurante','Mucho Más Restaurante','Cocina creativa (panceta coreana, vieiras) con servicio de primer nivel; los anfitriones Tim y Gary lo bordan.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90439','restaurante','El Fogón de Morales','Asador especialista en carnes maduradas (T-bone) y entrantes; clásico de la zona.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90449','restaurante','Taberna La Mari','Cocina casera con sabor y terraza acogedora; trato de Mari que te hace sentir en casa.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90449','restaurante','Restaurante El Parque','Solomillo a la pimienta y empanada mozárabe junto al parque; cocina muy cuidada a buen precio.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90494','restaurante','Panema Gastrobar','Gastrobar de risotto y tapeo de producto; uno de los más concurridos y mejor valorados.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90494','restaurante','Restaurante El Parque','Tapas, bocadillos y arroces; cocina rápida y rica con servicio muy atento.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90671','restaurante','Andra Mari','Cocina vasca de raíz con producto de caserío y vistas al valle. Una Estrella Michelin.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90736','restaurante','Bar La Esencia de la Alpujarra','Tapas exquisitas con producto muy cuidado; trato excepcional, de lo mejor de la comarca.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90736','restaurante','Restaurante El Canario','Tapas de montaña y cordero en un hostal con hosts entrañables; cocina honesta.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90947','restaurante','La Revelía','Sólida base vasca reinterpretada con técnica. Una Estrella Michelin (2026) y Recomendado Sol Sostenible de la Guía Repsol.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90947','restaurante','Boroa','Alta cocina vasca en un caserío del siglo XVI. Una Estrella Michelin.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90949','restaurante','Asador Etxebarri (Chef Bittor Arginzoniz)','Maestría absoluta de la brasa y el producto. Una Estrella Michelin y Tres Soles Repsol; referencia recurrente en la cima de The World''s 50 Best.','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90965','restaurante','Restaurante Villa','Cocina casera y hamburguesas con una gran selección de whisky; ambiente elegante.','gastronomia_ampliacion');

